using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class CrewlisleBranch : LayoutBase
{
    public CrewlisleBranch()
    {
        Name = LayoutNamesEnums.CrewlisleBranch;
        Owner = "Peter Goodman";
        Description = "Crewlisle is a fictitious part of the West Coast Main Line in North West England between the mid 1950s and mid 1980s, with overhead electrification arriving in the early 1960s. It is Lenz DCC controlled on three interconnected levels with at least two and sometimes four locomotives running simultaneously, and is built for entertainment rather than strict prototype fidelity. There are 52 locomotives that regularly ran on the WCML - steam, diesel and electric in a variety of liveries, including 10001 in black, a Blue Pullman, an HST, an APT, a couple of visitors and Thomas the Tank Engine for younger viewers - with four steam and seven diesel locomotives sound fitted, alongside 49 passenger and parcels coaches and 112 wagons, all in 2.6 square metres and with no fiddle yard. The fiddle yard is replaced by 14 removable 1370mm cassettes stored on a rack under the middle baseboard, each forming part of the reversing loop inside the operating well, plus two 1650mm cassettes that hold a six coach rake including locomotive, the APT or the Blue Pullman. The reversing loop leaves the main line under the signal cabin, runs down the inside of the operating well and under the high level goods yard before rejoining the main line under the coaling stage, and trains can leave it from either direction.";
    }
}
